"""Original CPU 3-D timeline/audio teaching lab. Not the author's source or Opus output."""
from pathlib import Path
import math,json,hashlib,sys,subprocess,wave,datetime,time
import numpy as np
from PIL import Image,ImageDraw,ImageFont
P=Path(__file__).resolve().parent;O=P/'out';O.mkdir(exist_ok=True)
DUR=13;FPS=24;W,H=640,360;SR=48000
BEATS=[{'t':.4,'event':'enter'},{'t':1.6,'event':'land'},{'t':3.5,'event':'orbit'},{'t':8.5,'event':'reframe'},{'t':11.2,'event':'settle'}]
T={e['event']:e['t'] for e in BEATS}
def smooth(x):x=max(0,min(1,x));return x*x*(3-2*x)
def interp(t,keys):
 if t<=keys[0][0]:return keys[0][1]
 for (a,x),(b,y) in zip(keys,keys[1:]):
  if t<=b:return x+(y-x)*smooth((t-a)/(b-a))
 return keys[-1][1]
def pose(t):
 t=max(0,min(DUR,t));return {'x':interp(t,[(0,-2.8),(T['enter'],-2.8),(T['land'],0),(T['orbit'],0),(T['reframe'],.6),(T['settle'],0),(13,0)]),'yaw':interp(t,[(0,-1.1),(T['land'],.1),(T['orbit'],.1),(T['reframe'],math.pi*1.75),(T['settle'],math.pi*2),(13,math.pi*2)]),'pitch':interp(t,[(0,.3),(T['land'],-.14),(T['orbit'],-.14),(T['reframe'],.26),(T['settle'],0),(13,0)]),'scale':interp(t,[(0,.3),(T['land'],1),(T['orbit'],1),(T['reframe'],1.4),(T['settle'],1),(13,1)])}
VERT=np.array([[-1,-1,-.25],[1,-1,-.25],[1,1,-.25],[-1,1,-.25],[-1,-1,.25],[1,-1,.25],[1,1,.25],[-1,1,.25]],float)
FACES=[(0,1,2,3),(4,7,6,5),(0,4,5,1),(3,2,6,7),(0,3,7,4),(1,5,6,2)]
COLORS=[(0,80,155),(0,225,240),(0,120,210),(255,145,25),(0,155,200),(15,100,180)]
def transform(v,t):
 s=pose(t);y=s['yaw'];x=s['pitch'];ry=np.array([[math.cos(y),0,math.sin(y)],[0,1,0],[-math.sin(y),0,math.cos(y)]]);rx=np.array([[1,0,0],[0,math.cos(x),-math.sin(x)],[0,math.sin(x),math.cos(x)]]);q=(v@ry.T@rx.T)*s['scale'];q[:,0]+=s['x'];return q
def project(q):
 z=6-q[:,2];assert np.min(z)>0;return np.column_stack([W/2+q[:,0]*410/z,H/2-q[:,1]*410/z])
def frame(t):
 im=Image.new('RGB',(W,H),(8,18,37));d=ImageDraw.Draw(im);d.ellipse((160,260,480,285),fill=(13,39,65));q=transform(VERT,t);pts=project(q)
 for face in sorted(FACES,key=lambda f:float(q[list(f),2].mean())):d.polygon([tuple(pts[i]) for i in face],fill=COLORS[FACES.index(face)],outline=(80,235,255))
 # White symbol on the front plane follows the same 3-D transform, not a screen overlay.
 for cx,cy in [(-.42,.35),(.35,.35),(-.42,-.4),(.35,-.4)]:
  v=np.array([[cx,cy,.251],[cx+.38,cy,.251],[cx+.38,cy+.38,.251],[cx,cy+.38,.251]])
  if math.cos(pose(t)['yaw'])>0:d.polygon([tuple(v) for v in project(transform(v,t))],fill=(245,254,255))
 font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',20);small=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',12)
 d.text((24,20),'KINETIC / CODED MOTION',font=font,fill=(225,249,255));d.text((24,328),f'ORIGINAL CPU 3D STUDY  |  t={t:05.2f}s',font=small,fill=(80,190,220));return im
# Exact standard sRGB transfer, not naive gamma-space averaging.
def linear(a):a=a/255.;return np.where(a<=.04045,a/12.92,((a+.055)/1.055)**2.4)
def srgb(a):return np.clip(np.rint(np.where(a<=.0031308,a*12.92,1.055*np.maximum(a,0)**(1/2.4)-.055)*255),0,255).astype(np.uint8)
def timeline():
 a=[pose(t) for t in [0,1.6,8.5,13]];b={t:pose(t) for t in [13,8.5,1.6,0]};assert a==[b[t] for t in [0,1.6,8.5,13]]
 delta=max(abs(pose(e['t']-1e-5)[k]-pose(e['t']+1e-5)[k]) for e in BEATS for k in pose(0));assert delta<.001
 assert smooth(0)==0 and smooth(1)==1
 black=np.zeros((1,1,3));white=np.full((1,1,3),255.);avg=int(srgb((linear(black)+linear(white))/2)[0,0,0]);assert avg==188
 durations=[1.2,1.9,5,2.7,1.8];out={'out_of_order_seek_identical':True,'max_boundary_delta':delta,'linear_light_black_white_average':avg,'gamma_space_average':128,'frames':DUR*FPS,'samples_audio':DUR*SR,'duration_ratio':max(durations)/min(durations),'note':'continuous parameters only; not proof of subjective shot continuity or GPU rendering'};save('timeline',out);(P/'beat-sheet.json').write_text(json.dumps({'duration':DUR,'fps':FPS,'sample_rate':SR,'beats':BEATS},indent=2));print(json.dumps(out))
def audio():
 n=DUR*SR;x=np.zeros(n,np.float64);marks=[]
 for k,e in enumerate(BEATS):
  start=round(e['t']*SR);length=int(.24*SR);t=np.arange(length)/SR;freq=220*2**((k%3)/12);pulse=.4*np.exp(-t*22)*np.sin(2*np.pi*(freq*t+40*(1-np.exp(-t*15))/15));x[start:start+length]+=pulse;marks.append({'event':e['event'],'sample':start,'time':start/SR,'error':abs(start/SR-e['t']),'nearest_video_frame':round(e['t']*FPS),'nearest_frame_error_seconds':abs(round(e['t']*FPS)/FPS-e['t'])})
 # Quiet original harmonic bed, faded at both ends. Not generated by an AI music service.
 t=np.arange(n)/SR;fade=np.minimum(np.minimum(t/.8,(DUR-t)/.8),1);x+=.06*np.maximum(fade,0)*(np.sin(2*np.pi*110*t)+.5*np.sin(2*np.pi*165*t));peak=float(np.max(np.abs(x)));assert peak<1
 with wave.open(str(O/'score.wav'),'wb') as f:f.setnchannels(1);f.setsampwidth(2);f.setframerate(SR);f.writeframes(np.rint(x*32767).astype('<i2').tobytes())
 out={'samples':n,'duration_seconds':n/SR,'peak':peak,'clipped_samples':int(np.sum(abs(x)>=1)),'event_marks':marks};save('audio',out);print(json.dumps(out))
def render():
 d=O/'frames';d.mkdir(exist_ok=True);start=time.monotonic()
 # Four centered 180-degree shutter samples per frame. CPU polygon rasterizer, no browser.
 for i in range(DUR*FPS):
  t=i/FPS;times=[max(0,min(DUR-1e-6,t+(.5/FPS)*((j+.5)/4-.5))) for j in range(4)];arr=sum(linear(np.asarray(frame(tk)).astype(float)) for tk in times)/4;Image.fromarray(srgb(arr)).save(d/f'{i:05}.png',compress_level=1)
  if i%72==0:print('rendered',i,flush=True)
 out={'frames':DUR*FPS,'size':[W,H],'fps':FPS,'duration_seconds':DUR,'shutter_degrees':180,'samples_per_frame':4,'renderer':'original CPU perspective polygons, not Three.js/WebGL/onetake','wall_seconds':round(time.monotonic()-start,3)};save('render',out);print(json.dumps(out))
def encode():
 cmd=['ffmpeg','-hide_banner','-loglevel','error','-y','-framerate',str(FPS),'-i',str(O/'frames/%05d.png'),'-i',str(O/'score.wav'),'-c:v','libx264','-preset','fast','-crf','22','-pix_fmt','yuv420p','-c:a','aac','-b:a','128k','-movflags','+faststart',str(O/'study.mp4')];subprocess.run(cmd,check=True)
 meta=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_streams','-show_format','-of','json',str(O/'study.mp4')]));save('probe',meta);v=next(x for x in meta['streams'] if x['codec_type']=='video');a=next(x for x in meta['streams'] if x['codec_type']=='audio');assert int(v['nb_read_frames'])==312;assert abs(float(v['duration'])-13)<.001;assert abs(float(a['duration'])-13)<.05
 subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-i',str(O/'study.mp4'),'-f','null','-'],check=True)
 subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-i',str(O/'study.mp4'),'-vf','fps=1/2,scale=400:225,tile=4x2','-frames:v','1','-y',str(O/'contact.png')],check=True)
 hashes=[hashlib.sha256((O/'frames'/f'{i:05}.png').read_bytes()).hexdigest() for i in [0,38,84,204,269,311]];assert len(set(hashes))==6;out={'video_frames':int(v['nb_read_frames']),'video_duration':v['duration'],'audio_duration':a['duration'],'decoded_without_errors':True,'sampled_unique_frame_hashes':6,'sha256_mp4':hashlib.sha256((O/'study.mp4').read_bytes()).hexdigest(),'command':cmd};save('encode',out);print(json.dumps(out))
def source_audit():
 root=P.parent/'sources/onetake';f=root/'scripts/render.py';meta=json.loads((P/'source-manifest.json').read_text());
 if f.exists():text=f.read_text()
 else:
  import urllib.request
  text=urllib.request.urlopen('https://raw.githubusercontent.com/'+meta['repo']+'/'+meta['sha']+'/'+meta['path'],timeout=30).read().decode()
 tokens=['window.__seek','window.__ready','SRGB_TO_LIN','__motion','--workers','--gpu'];assert all(t in text for t in tokens);out={'source_tokens':tokens,'tokens_verified':len(tokens),'sha':meta['sha'],'license':'PolyForm Noncommercial 1.0.0','upstream_renderer_executed':False,'blender_executed':False,'paid_model_calls':0};save('source-audit',out);print(json.dumps(out))
def save(name,data):(O/(name+'-result.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2))
if __name__=='__main__':globals()[sys.argv[1]]()
